19	export const CURRENT_NAV_GROUP_ID = 'core.chrome.currentNavGroupId';
20	
21	/** @public */
22	export interface ChromeRegistrationNavLink {
23	  id: string;
24	  title?: string;
25	  category?: AppCategory;
26	  order?: number;
27	
28	  /**
29	   * link with parentNavLinkId field will be displayed as nested items in navigation.
30	   */
31	  parentNavLinkId?: string;
32	
33	  /**
34	   * If the nav link should be shown in 'all' nav group
35	   */
36	  showInAllNavGroup?: boolean;
37	}
38	
39	export type NavGroupItemInMap = ChromeNavGroup & {
40	  navLinks: ChromeRegistrationNavLink[];
41	};
42	
43	export type ChromeNavGroupUpdater = (navGroup: ChromeNavGroup) => Partial<ChromeNavGroup> | void;
44	
45	export interface ChromeNavGroupServiceSetupContract {
46	  addNavLinksToGroup: (navGroup: ChromeNavGroup, navLinks: ChromeRegistrationNavLink[]) => void;
47	  /**
48	   * Get a boolean value to indicates whether use case is enabled
49	   */
50	  getNavGroupEnabled: () => boolean;
51	  registerNavGroupUpdater: (navGroupUpdater: Observable<ChromeNavGroupUpdater>) => () => void;
52	}
53	
54	export interface ChromeNavGroupServiceStartContract {
55	  getNavGroupsMap$: () => Observable<Record<string, NavGroupItemInMap>>;
56	  getNavGroupEnabled: ChromeNavGroupServiceSetupContract['getNavGroupEnabled'];
57	  /**
58	   * Get an observable of the current selected nav group
59	   */
60	  getCurrentNavGroup$: () => Observable<NavGroupItemInMap | undefined>;
61	
62	  /**
63	   * Set current selected nav group
64	   * @param navGroupId The id of the nav group to be set as current
65	   */
66	  setCurrentNavGroup: (navGroupId: string | undefined) => void;
67	}
