+            setIsNavOpen(false);
+            if (toggleCollapsibleNavRef.current) {
+              toggleCollapsibleNavRef.current.focus();
+            }
+          }}
+          customNavLink$={observables.customNavLink$}
+          logos={logos}
+        />
+      </header>
+    </>
+  );
+}
